"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[43610],{92896:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"NpcCollisionService","desc":"Places every BasePart of every faction-tagged Model (`\\"EnemyNPC\\"` /\\n`\\"FriendlyNPC\\"`, see Factions) into the `Character` collision group (see\\nCollisionGroups), so thrown charges (`WeaponProjectile`) and dropped\\nmaterials (`DroppedMaterial`) pass through NPCs exactly as they pass through\\nplayers. This is the non-player sibling of CharacterCollisionService: players\\nare handled by Players events there, NPCs are handled by the faction tags\\nhere.\\n\\nThose same faction tags gate direct Humanoid damage and friendly-fire in\\nCombatService (see Factions), so one tag makes a Model both\\nprojectile-pass-through and damageable.\\n\\nParts that stream in after tagging (R15 limbs, accessories) are caught via a\\nper-model `DescendantAdded` connection owned by a per-model Janitor. The\\nJanitor is torn down when the tag is removed OR the model is destroyed \u2014\\n`GetInstanceRemovedSignal` fires in both cases, so no separate `Destroying`\\nbackstop is needed.","realm":["Server"],"source":{"line":24,"path":"src/ServerScriptService/NpcCollisionService.server.luau"}}')}}]);